-- 資料來源：衛生福利部 TW Core IG，臺灣壽險公會傷害保險個人職業分類表。
-- Canonical URL: https://twcore.mohw.gov.tw/ig/twcore/CodeSystem/occupation-lia-roc-tw
-- Source version: 2023-06-01；英文名稱來源未提供，禁止自行翻譯。
ALTER TABLE new_contract.code_definition
  ADD COLUMN code_group_description_zh_tw VARCHAR(255),
  ADD COLUMN code_field_description_zh_tw VARCHAR(255),
  ADD COLUMN classification_code VARCHAR(8),
  ADD COLUMN classification_description_zh_tw VARCHAR(255),
  ADD COLUMN breakdown_code VARCHAR(8),
  ADD COLUMN breakdown_description_zh_tw VARCHAR(255),
  ADD COLUMN nature_of_work_zh_tw VARCHAR(255),
  ADD COLUMN source_system VARCHAR(255),
  ADD COLUMN source_version VARCHAR(32);

UPDATE new_contract.code_definition SET code_group_description_zh_tw = '客戶 KYC', code_field_description_zh_tw = CASE code_field WHEN 'source_of_funds_code' THEN '資金來源' WHEN 'insurance_purpose_code' THEN '投保目的' WHEN 'occupation_code' THEN '職業' END WHERE code_group = 'customer-kyc';

DELETE FROM new_contract.code_definition WHERE code_group = 'customer-kyc' AND code_field = 'occupation_code';


